// -----------------------------------------------------------------------------
// Journey Boarding — Start Journey Request DTO
// -----------------------------------------------------------------------------

import { ApiPropertyOptional } from '@nestjs/swagger';

import {
  IsDateString,
  IsOptional,
  IsString,
  MaxLength,
  MinLength,
} from 'class-validator';

/**
 * REST request DTO for starting a Journey.
 *
 * The Journey Boarding public identifier comes from the route parameter.
 * Correlation metadata is generated by the backend.
 *
 * This DTO contains transport primitives only.
 * The presentation/application mapping layer converts journeyStartedAt
 * into a Date before constructing StartJourneyCommand.
 */
export class StartJourneyDto {
  // ===========================================================================
  // Causation
  // ===========================================================================

  /**
   * Optional identifier of the command or event that caused this request.
   */
  @ApiPropertyOptional({
    description: 'Identifier of the command or event that caused this request.',
    example: 'cmd-01J8XYZ789',
    minLength: 1,
    maxLength: 200,
  })
  @IsOptional()
  @IsString()
  @MinLength(1)
  @MaxLength(200)
  causationId?: string;

  // ===========================================================================
  // Journey Start Timestamp
  // ===========================================================================

  /**
   * Optional timestamp at which the Journey started.
   *
   * When omitted, the domain uses the current time.
   */
  @ApiPropertyOptional({
    description: 'ISO-8601 timestamp representing when the Journey started.',
    example: '2026-08-19T10:45:00.000Z',
    format: 'date-time',
  })
  @IsOptional()
  @IsDateString()
  journeyStartedAt?: string;
}

// -----------------------------------------------------------------------------
// Default Export
// -----------------------------------------------------------------------------

export default StartJourneyDto;
